schema = protobuf.load([modulepath('protobuf'), '/tests/data/sensor_stream.proto']);
protobuf.enums(schema, 'Color')
bytes = protobuf.encode(schema, 'AllTypes', struct('f_enum', 'BLUE', 'r_enum', {{'RED', 'BLUE'}}));
value = protobuf.decode(schema, 'AllTypes', bytes, 'EnumsAsText', true);
disp(value.r_enum)
